CREATE FUNCTION public.next_sales_number(p_client text,p_type text,p_date date) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); code text; n bigint; fmt text; BEGIN IF NOT public.can_access_tenant_module(tid,CASE WHEN p_type='quotation' THEN 'quotations' ELSE 'orders' END) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; code:=regexp_replace(upper(btrim(p_client)),'[^A-Z0-9]','','g'); IF code='' OR p_date IS NULL THEN RAISE EXCEPTION 'Client dan tanggal wajib'; END IF; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(tid,code,p_type,1) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=public.document_sequences.sequence+1 RETURNING sequence INTO n; SELECT doc_numbering->>p_type INTO fmt FROM public.tenant_settings WHERE tenant_id=tid; IF fmt IS NULL OR (p_type='invoice' AND fmt='{SEQ}/SDY/INV/{CLIENT}/{MM}{YYYY}') THEN fmt:=CASE p_type WHEN 'order' THEN 'PO' WHEN 'quotation' THEN 'QUO' ELSE 'INV' END||'/{CLIENT}/{YYYY}/{MM}/{SEQ}'; END IF; RETURN replace(replace(replace(replace(replace(fmt,'{CLIENT}',code),'{KODE_CLIENT}',code),'{YYYY}',to_char(p_date,'YYYY')),'{MM}',to_char(p_date,'MM')),'{SEQ}',n::text); END $$;
REVOKE ALL ON FUNCTION public.next_sales_number(text,text,date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.next_sales_number(text,text,date) TO service_role;
CREATE FUNCTION public.sales_totals(p_entity text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE doc jsonb; raw numeric; net numeric; dd numeric; tax numeric; paid numeric:=0; dv numeric; dt text; fp text; items jsonb; tid uuid:=public.active_tenant_id(); BEGIN IF p_entity NOT IN ('orders','quotations') OR NOT (public.can_access_tenant_module(tid,CASE WHEN p_entity='orders' THEN 'orders' ELSE 'quotations' END) OR (p_entity='orders' AND public.can_access('finance'))) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; IF p_entity='orders' THEN SELECT to_jsonb(o) INTO doc FROM public.orders o WHERE id=p_id AND tenant_id=tid AND deleted_at IS NULL; SELECT COALESCE(sum(qty*price),0),COALESCE(sum(qty*price-CASE WHEN discount_type='percent' THEN qty*price*discount_value/100 ELSE discount_value END),0),COALESCE(jsonb_agg(jsonb_build_object('name',item_name,'qty',qty,'price',price,'discount_type',discount_type,'discount_value',discount_value) ORDER BY position),'[]') INTO raw,net,items FROM public.order_items WHERE order_id=p_id AND tenant_id=tid AND deleted_at IS NULL; SELECT COALESCE(sum(amount),0) INTO paid FROM public.payments WHERE order_id=p_id AND tenant_id=tid AND voided_at IS NULL; ELSE SELECT to_jsonb(q) INTO doc FROM public.quotations q WHERE id=p_id AND tenant_id=tid AND deleted_at IS NULL; SELECT COALESCE(sum(qty*price),0),COALESCE(sum(qty*price-CASE WHEN discount_type='percent' THEN qty*price*discount_value/100 ELSE discount_value END),0),COALESCE(jsonb_agg(jsonb_build_object('name',item_name,'qty',qty,'price',price,'discount_type',discount_type,'discount_value',discount_value) ORDER BY position),'[]') INTO raw,net,items FROM public.quotation_items WHERE quotation_id=p_id AND tenant_id=tid AND deleted_at IS NULL; END IF; IF doc IS NULL THEN RAISE EXCEPTION 'Dokumen tidak ditemukan'; END IF; dt:=doc->>'discount_type'; dv:=(doc->>'discount_value')::numeric; dd:=CASE WHEN dt='percent' THEN net*dv/100 ELSE dv END; IF net<0 OR dd>net OR (dt='percent' AND dv>100) THEN RAISE EXCEPTION 'Diskon melebihi nilai dokumen'; END IF; tax:=CASE WHEN (doc->>'tax_enabled')::boolean THEN round((net-dd)*(doc->>'tax_rate')::numeric/100,2) ELSE 0 END; fp:=md5(jsonb_build_object('client',doc->>'client_name','date',COALESCE(doc->>'invoice_date',doc->>'document_date'),'items',items,'discount_type',dt,'discount_value',dv,'tax',tax)::text); RETURN jsonb_build_object('subtotal',raw,'item_discount',raw-net,'document_discount',dd,'discount',raw-net+dd,'effective_discount_pct',CASE WHEN raw>0 THEN (raw-net+dd)*100/raw ELSE 0 END,'tax',tax,'total',round(net-dd+tax,2),'paid',paid,'balance',round(net-dd+tax-paid,2),'fingerprint',fp,'state',CASE WHEN p_entity='quotations' THEN CASE WHEN NULLIF(doc->>'valid_until','')::date<(now() AT TIME ZONE 'Asia/Jakarta')::date AND doc->>'status' NOT IN ('disetujui','ditolak') THEN 'kedaluwarsa' ELSE doc->>'status' END WHEN doc->>'invoice_state'='cancelled' THEN 'dibatalkan' WHEN doc->>'invoice_state'='pending' THEN 'menunggu persetujuan' WHEN doc->>'invoice_state'='draft' THEN 'draft' WHEN round(net-dd+tax-paid,2)<=0 THEN 'lunas' WHEN NULLIF(doc->>'due_date','')::date < (now() AT TIME ZONE 'Asia/Jakarta')::date THEN 'jatuh tempo' WHEN paid>0 THEN 'sebagian dibayar' ELSE 'terbit' END); END $$;
GRANT EXECUTE ON FUNCTION public.sales_totals(text,uuid) TO authenticated; REVOKE EXECUTE ON FUNCTION public.sales_totals(text,uuid) FROM PUBLIC,anon;
CREATE FUNCTION public.save_sales_document(p_entity text,p_id uuid,p_doc jsonb,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); oid uuid; olddoc jsonb; d date; num text; item jsonb; iid uuid; keep uuid[]:='{}'; dt text; dv numeric; totals jsonb; threshold numeric; mod text; reason text; rate numeric; itbl text; fk text; BEGIN mod:=CASE p_entity WHEN 'orders' THEN 'orders' WHEN 'quotations' THEN 'quotations' END; IF mod IS NULL OR NOT public.can_access_tenant_module(tid,mod) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; IF p_doc ? 'tenant_id' AND (p_doc->>'tenant_id')::uuid IS DISTINCT FROM tid THEN RAISE EXCEPTION 'Tenant palsu'; END IF; IF NULLIF(btrim(p_doc->>'client_name'),'') IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Client dan minimal satu item wajib'; END IF; d:=COALESCE(NULLIF(p_doc->>'document_date','')::date,NULLIF(p_doc->>'invoice_date','')::date,(now() AT TIME ZONE 'Asia/Jakarta')::date); dt:=COALESCE(p_doc->>'discount_type','percent'); dv:=COALESCE((p_doc->>'discount_value')::numeric,0); SELECT ppn_rate,discount_approval_threshold_pct INTO rate,threshold FROM public.tenant_settings WHERE tenant_id=tid; IF p_id IS NOT NULL THEN EXECUTE format('SELECT to_jsonb(r) FROM public.%I r WHERE id=$1 AND tenant_id=$2 AND deleted_at IS NULL FOR UPDATE',p_entity) INTO olddoc USING p_id,tid; IF olddoc IS NULL THEN RAISE EXCEPTION 'Dokumen tidak ditemukan'; END IF; IF olddoc->>'invoice_state' IN ('issued','cancelled') OR olddoc->>'converted_order_id' IS NOT NULL OR (p_entity='quotations' AND olddoc->>'status'<>'draft') THEN RAISE EXCEPTION 'Dokumen terkunci'; END IF; END IF; num:=NULLIF(btrim(p_doc->>'number'),''); reason:=btrim(COALESCE(p_doc->>'number_reason','')); IF num IS NOT NULL AND num IS DISTINCT FROM (CASE WHEN p_entity='orders' THEN olddoc->>'order_number' ELSE olddoc->>'quotation_number' END) AND (NOT public.is_master() OR reason='') THEN RAISE EXCEPTION 'Nomor manual hanya Master dengan alasan'; END IF;
IF p_entity='orders' THEN IF p_id IS NULL THEN num:=COALESCE(num,public.next_sales_number(p_doc->>'client_name','order',d)); INSERT INTO public.orders(tenant_id,client_id,client_name,client_address,order_number,order_date,invoice_date,due_date,section,notes,created_by,discount_type,discount_value,tax_enabled,tax_rate) VALUES(tid,NULLIF(p_doc->>'client_id','')::uuid,btrim(p_doc->>'client_name'),p_doc->>'client_address',num,d,d,NULLIF(p_doc->>'due_date','')::date,p_doc->>'section',p_doc->>'notes',auth.uid()::text,dt,dv,COALESCE((p_doc->>'tax_enabled')::boolean,false),rate) RETURNING id INTO oid; ELSE oid:=p_id; UPDATE public.orders SET client_id=NULLIF(p_doc->>'client_id','')::uuid,client_name=btrim(p_doc->>'client_name'),client_address=p_doc->>'client_address',order_number=COALESCE(num,order_number),order_date=d,invoice_date=d,due_date=NULLIF(p_doc->>'due_date','')::date,section=p_doc->>'section',notes=p_doc->>'notes',discount_type=dt,discount_value=dv,tax_enabled=COALESCE((p_doc->>'tax_enabled')::boolean,false),tax_rate=rate,invoice_state='draft',approved_fingerprint=NULL WHERE id=oid AND tenant_id=tid; END IF;
ELSE IF p_id IS NULL THEN num:=COALESCE(num,public.next_sales_number(p_doc->>'client_name','quotation',d)); INSERT INTO public.quotations(tenant_id,client_id,client_name,client_address,quotation_number,document_date,valid_until,due_date,notes,discount_type,discount_value,tax_enabled,tax_rate) VALUES(tid,NULLIF(p_doc->>'client_id','')::uuid,btrim(p_doc->>'client_name'),p_doc->>'client_address',num,d,NULLIF(p_doc->>'valid_until','')::date,NULLIF(p_doc->>'due_date','')::date,p_doc->>'notes',dt,dv,COALESCE((p_doc->>'tax_enabled')::boolean,false),rate) RETURNING id INTO oid; ELSE oid:=p_id; UPDATE public.quotations SET client_id=NULLIF(p_doc->>'client_id','')::uuid,client_name=btrim(p_doc->>'client_name'),client_address=p_doc->>'client_address',quotation_number=COALESCE(num,quotation_number),document_date=d,valid_until=NULLIF(p_doc->>'valid_until','')::date,due_date=NULLIF(p_doc->>'due_date','')::date,notes=p_doc->>'notes',discount_type=dt,discount_value=dv,tax_enabled=COALESCE((p_doc->>'tax_enabled')::boolean,false),tax_rate=rate,approved_fingerprint=NULL WHERE id=oid AND tenant_id=tid; END IF; END IF;
itbl:=CASE WHEN p_entity='orders' THEN 'order_items' ELSE 'quotation_items' END; fk:=CASE WHEN p_entity='orders' THEN 'order_id' ELSE 'quotation_id' END;
FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP IF NULLIF(btrim(item->>'item_name'),'') IS NULL OR (item->>'qty')::numeric<=0 OR (item->>'price')::numeric<0 OR (item->>'discount_value')::numeric<0 OR (item->>'discount_type'='percent' AND (item->>'discount_value')::numeric>100) OR (item->>'discount_type'='amount' AND (item->>'discount_value')::numeric>(item->>'qty')::numeric*(item->>'price')::numeric) THEN RAISE EXCEPTION 'Item, qty, harga atau diskon tidak valid'; END IF; iid:=NULLIF(item->>'id','')::uuid; IF iid IS NOT NULL THEN EXECUTE format('SELECT id FROM public.%I WHERE id=$1 AND %I=$2 AND tenant_id=$3 AND deleted_at IS NULL',itbl,fk) INTO iid USING iid,oid,tid; IF iid IS NULL THEN RAISE EXCEPTION 'Item tidak berizin'; END IF; EXECUTE format('UPDATE public.%I SET item_name=$2,qty=$3,price=$4,unit=$5,position=$6,discount_type=$7,discount_value=$8 WHERE id=$1 AND tenant_id=$9',itbl) USING iid,btrim(item->>'item_name'),(item->>'qty')::numeric,(item->>'price')::numeric,COALESCE(item->>'unit','pcs'),cardinality(keep)+1,COALESCE(item->>'discount_type','percent'),COALESCE((item->>'discount_value')::numeric,0),tid; ELSE EXECUTE format('INSERT INTO public.%I(tenant_id,%I,item_name,qty,price,unit,position,discount_type,discount_value) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id',itbl,fk) INTO iid USING tid,oid,btrim(item->>'item_name'),(item->>'qty')::numeric,(item->>'price')::numeric,COALESCE(item->>'unit','pcs'),cardinality(keep)+1,COALESCE(item->>'discount_type','percent'),COALESCE((item->>'discount_value')::numeric,0); END IF; keep:=array_append(keep,iid); END LOOP;
IF EXISTS(SELECT 1 FROM public.user_roles WHERE tenant_id=tid AND user_id=auth.uid() AND role='master') THEN EXECUTE format('UPDATE public.%I SET deleted_at=now(),deleted_by=$1,delete_reason=$2 WHERE %I=$3 AND tenant_id=$4 AND deleted_at IS NULL AND NOT(id=ANY($5))',itbl,fk) USING auth.uid(),COALESCE(NULLIF(p_doc->>'removal_reason',''),'Item dikeluarkan dari draft'),oid,tid,keep; ELSE EXECUTE format('SELECT id FROM public.%I WHERE %I=$1 AND tenant_id=$2 AND deleted_at IS NULL AND NOT(id=ANY($3)) LIMIT 1',itbl,fk) INTO iid USING oid,tid,keep; IF iid IS NOT NULL THEN RAISE EXCEPTION 'Staff harus mengarsipkan item melalui persetujuan'; END IF; END IF;
totals:=public.sales_totals(p_entity,oid); UPDATE public.approval_requests SET status='rejected',decided_by=auth.uid(),decided_at=now(),decision_reason='Draft diperbarui; permintaan digantikan' WHERE tenant_id=tid AND entity_id=oid AND type='discount' AND status='pending'; IF (totals->>'effective_discount_pct')::numeric>threshold THEN IF p_entity='orders' THEN UPDATE public.orders SET invoice_state='pending' WHERE id=oid; END IF; INSERT INTO public.approval_requests(tenant_id,type,entity_type,entity_id,requested_by,reason,payload) VALUES(tid,'discount',p_entity,oid,auth.uid(),'Persetujuan diskon dokumen',totals||jsonb_build_object('number',COALESCE(num,olddoc->>'order_number',olddoc->>'quotation_number'),'client',p_doc->>'client_name')); END IF; IF reason<>'' AND num IS NOT NULL THEN INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(tid,auth.uid(),'manual_number',p_entity,oid,jsonb_build_object('before',olddoc,'number',num,'reason',reason)); END IF; RETURN oid; END $$;
GRANT EXECUTE ON FUNCTION public.save_sales_document(text,uuid,jsonb,jsonb) TO authenticated; REVOKE EXECUTE ON FUNCTION public.save_sales_document(text,uuid,jsonb,jsonb) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.save_order_atomic(p_order_id uuid,p_order jsonb,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.save_sales_document('orders',p_order_id,p_order,p_items); END $$;
CREATE FUNCTION public.sync_invoice_receivable(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; totals jsonb; rid uuid; BEGIN SELECT * INTO o FROM public.orders WHERE id=p_id AND tenant_id=public.active_tenant_id(); totals:=public.sales_totals('orders',p_id); SELECT id INTO rid FROM public.receivables WHERE tenant_id=o.tenant_id AND order_id=o.id; IF rid IS NULL THEN SELECT id INTO rid FROM public.receivables WHERE tenant_id=o.tenant_id AND invoice_no=o.invoice_number AND order_id IS NULL AND deleted_at IS NULL ORDER BY created_at LIMIT 1; END IF; IF rid IS NOT NULL THEN UPDATE public.receivables SET order_id=o.id,client_name=o.client_name,invoice_no=o.invoice_number,invoice_total=(totals->>'total')::numeric,amount=CASE WHEN o.invoice_state='cancelled' THEN 0 ELSE (totals->>'balance')::numeric END,status=CASE WHEN o.invoice_state='cancelled' OR (totals->>'balance')::numeric<=0 THEN 'Lunas' ELSE 'Belum Tertagih' END,invoice_date=o.invoice_date,due_date=o.due_date WHERE id=rid; ELSE INSERT INTO public.receivables(tenant_id,order_id,client_name,invoice_no,invoice_total,amount,invoice_date,due_date,status) VALUES(o.tenant_id,o.id,o.client_name,o.invoice_number,(totals->>'total')::numeric,(totals->>'balance')::numeric,o.invoice_date,o.due_date,CASE WHEN (totals->>'balance')::numeric<=0 THEN 'Lunas' ELSE 'Belum Tertagih' END); END IF; END $$;
REVOKE ALL ON FUNCTION public.sync_invoice_receivable(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.issue_invoice(p_order_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; totals jsonb; threshold numeric; num text; snapshot jsonb; BEGIN IF NOT public.can_access('orders') THEN RAISE EXCEPTION 'Order tidak berizin'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF; IF o.invoice_state='issued' THEN RETURN o.invoice_number; END IF; IF o.invoice_state='cancelled' THEN RAISE EXCEPTION 'Invoice dibatalkan'; END IF; IF NOT EXISTS(SELECT 1 FROM public.order_items WHERE order_id=o.id AND tenant_id=o.tenant_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Item kosong'; END IF; totals:=public.sales_totals('orders',o.id); SELECT discount_approval_threshold_pct,to_jsonb(s)||jsonb_build_object('name',t.name) INTO threshold,snapshot FROM public.tenant_settings s JOIN public.tenants t ON t.id=s.tenant_id WHERE s.tenant_id=o.tenant_id; IF (totals->>'effective_discount_pct')::numeric>threshold AND o.approved_fingerprint IS DISTINCT FROM (totals->>'fingerprint') THEN RAISE EXCEPTION 'Diskon belum disetujui Master'; END IF; num:=COALESCE(o.invoice_number,public.next_sales_number(o.client_name,'invoice',o.invoice_date)); UPDATE public.orders SET invoice_number=num,invoice_state='issued',issued_at=now(),brand_snapshot=snapshot WHERE id=o.id; PERFORM public.sync_invoice_receivable(o.id); RETURN num; END $$;
GRANT EXECUTE ON FUNCTION public.issue_invoice(uuid) TO authenticated; REVOKE EXECUTE ON FUNCTION public.issue_invoice(uuid) FROM PUBLIC,anon;
CREATE FUNCTION public.record_payment(p_order_id uuid,p_amount numeric,p_date date,p_method text,p_reference text DEFAULT NULL,p_notes text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; balance numeric; pid uuid; BEGIN IF NOT public.can_access('finance') THEN RAISE EXCEPTION 'Finance tidak berizin'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL OR o.invoice_state<>'issued' THEN RAISE EXCEPTION 'Invoice belum terbit atau dibatalkan'; END IF; balance:=(public.sales_totals('orders',o.id)->>'balance')::numeric; IF p_amount IS NULL OR p_amount<=0 OR p_amount='NaN'::numeric OR p_amount>balance OR p_date IS NULL THEN RAISE EXCEPTION 'Pembayaran harus positif dan tidak melebihi sisa tagihan'; END IF; INSERT INTO public.payments(tenant_id,order_id,amount,payment_date,method,reference,notes,created_by) VALUES(o.tenant_id,o.id,p_amount,p_date,p_method,p_reference,p_notes,auth.uid()) RETURNING id INTO pid; PERFORM public.sync_invoice_receivable(o.id); RETURN pid; END $$;
GRANT EXECUTE ON FUNCTION public.record_payment(uuid,numeric,date,text,text,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.record_payment(uuid,numeric,date,text,text,text) FROM PUBLIC,anon;
CREATE FUNCTION public.void_payment(p_payment_id uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.payments; BEGIN IF NOT public.can_access('finance') OR NOT public.is_master() OR length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Void hanya Master Finance dengan alasan'; END IF; SELECT * INTO p FROM public.payments WHERE id=p_payment_id AND tenant_id=public.active_tenant_id(); PERFORM 1 FROM public.orders WHERE id=p.order_id AND tenant_id=p.tenant_id AND invoice_state='issued' FOR UPDATE; IF NOT FOUND OR p.voided_at IS NOT NULL THEN RAISE EXCEPTION 'Pembayaran tidak ditemukan atau sudah void'; END IF; UPDATE public.payments SET voided_at=now(),voided_by=auth.uid(),void_reason=btrim(p_reason) WHERE id=p.id AND voided_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Pembayaran sudah void'; END IF; PERFORM public.sync_invoice_receivable(p.order_id); END $$;
GRANT EXECUTE ON FUNCTION public.void_payment(uuid,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.void_payment(uuid,text) FROM PUBLIC,anon;
CREATE FUNCTION public.request_invoice_cancel(p_order_id uuid,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; rid uuid; BEGIN IF NOT public.can_access('orders') OR length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Order dan alasan wajib'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL OR o.invoice_state<>'issued' THEN RAISE EXCEPTION 'Invoice belum terbit'; END IF; INSERT INTO public.approval_requests(tenant_id,type,entity_type,entity_id,requested_by,reason,payload) VALUES(o.tenant_id,'cancel','orders',o.id,auth.uid(),btrim(p_reason),jsonb_build_object('number',o.invoice_number,'client',o.client_name)) ON CONFLICT DO NOTHING RETURNING id INTO rid; RETURN rid; END $$;
GRANT EXECUTE ON FUNCTION public.request_invoice_cancel(uuid,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.request_invoice_cancel(uuid,text) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.decide_approval(p_request_id uuid,p_approve boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.approval_requests; totals jsonb; BEGIN IF NOT public.is_master() OR length(btrim(COALESCE(p_reason,'')))=0 THEN RAISE EXCEPTION 'Master dan alasan keputusan wajib'; END IF; SELECT * INTO r FROM public.approval_requests WHERE id=p_request_id AND tenant_id=public.active_tenant_id() AND status='pending' FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Permintaan tidak ditemukan'; END IF; IF p_approve AND r.type='delete' THEN PERFORM public.archive_entity(r.entity_type,r.entity_id,r.reason||' / Disetujui: '||p_reason); ELSIF r.type='discount' THEN IF r.entity_type='orders' THEN PERFORM 1 FROM public.orders WHERE id=r.entity_id AND tenant_id=r.tenant_id AND deleted_at IS NULL FOR UPDATE; ELSE PERFORM 1 FROM public.quotations WHERE id=r.entity_id AND tenant_id=r.tenant_id AND deleted_at IS NULL FOR UPDATE; END IF; totals:=public.sales_totals(r.entity_type,r.entity_id); IF p_approve AND (totals->>'fingerprint') IS DISTINCT FROM (r.payload->>'fingerprint') THEN RAISE EXCEPTION 'Dokumen berubah, ajukan persetujuan ulang'; END IF; IF r.entity_type='orders' THEN UPDATE public.orders SET approved_fingerprint=CASE WHEN p_approve THEN totals->>'fingerprint' ELSE NULL END,invoice_state=CASE WHEN p_approve THEN 'draft' ELSE 'pending' END WHERE id=r.entity_id AND tenant_id=r.tenant_id AND invoice_state IN ('draft','pending'); ELSE UPDATE public.quotations SET approved_fingerprint=CASE WHEN p_approve THEN totals->>'fingerprint' ELSE NULL END WHERE id=r.entity_id AND tenant_id=r.tenant_id; END IF; ELSIF p_approve AND r.type='cancel' THEN PERFORM 1 FROM public.orders WHERE id=r.entity_id AND tenant_id=r.tenant_id AND invoice_state='issued' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invoice tidak ditemukan'; END IF; IF EXISTS(SELECT 1 FROM public.payments WHERE tenant_id=r.tenant_id AND order_id=r.entity_id AND voided_at IS NULL) THEN RAISE EXCEPTION 'Void pembayaran aktif terlebih dahulu dengan alasan'; END IF; UPDATE public.orders SET invoice_state='cancelled' WHERE id=r.entity_id AND tenant_id=r.tenant_id; PERFORM public.sync_invoice_receivable(r.entity_id); END IF; UPDATE public.approval_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decided_at=now(),decision_reason=btrim(p_reason) WHERE id=r.id; INSERT INTO public.notifications(tenant_id,user_id,message,request_id) VALUES(r.tenant_id,r.requested_by,CASE r.type WHEN 'discount' THEN 'Diskon' WHEN 'cancel' THEN 'Pembatalan invoice' ELSE 'Arsip' END||CASE WHEN p_approve THEN ' disetujui: ' ELSE ' ditolak: ' END||btrim(p_reason),r.id); INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(r.tenant_id,auth.uid(),'approval_decision',r.entity_type,r.entity_id,jsonb_build_object('request_id',r.id,'approved',p_approve,'reason',p_reason)); END $$;
CREATE FUNCTION public.set_quotation_status(p_id uuid,p_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quotations; totals jsonb; threshold numeric; BEGIN IF NOT public.can_access('quotations') OR p_status NOT IN ('draft','terkirim','disetujui','ditolak','kedaluwarsa') THEN RAISE EXCEPTION 'Tidak berizin atau status salah'; END IF; SELECT * INTO q FROM public.quotations WHERE id=p_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF q.id IS NULL OR q.converted_order_id IS NOT NULL THEN RAISE EXCEPTION 'Penawaran tidak ditemukan atau terkunci'; END IF; IF p_status IN ('terkirim','disetujui') THEN totals:=public.sales_totals('quotations',q.id); SELECT discount_approval_threshold_pct INTO threshold FROM public.tenant_settings WHERE tenant_id=q.tenant_id; IF (totals->>'effective_discount_pct')::numeric>threshold AND q.approved_fingerprint IS DISTINCT FROM (totals->>'fingerprint') THEN RAISE EXCEPTION 'Diskon belum disetujui'; END IF; IF q.valid_until<(now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Penawaran kedaluwarsa'; END IF; END IF; UPDATE public.quotations SET status=p_status,brand_snapshot=CASE WHEN p_status IN ('terkirim','disetujui') THEN COALESCE(brand_snapshot,(SELECT to_jsonb(s)||jsonb_build_object('name',t.name) FROM public.tenant_settings s JOIN public.tenants t ON t.id=s.tenant_id WHERE s.tenant_id=q.tenant_id)) ELSE brand_snapshot END WHERE id=q.id; END $$;
GRANT EXECUTE ON FUNCTION public.set_quotation_status(uuid,text) TO authenticated; REVOKE EXECUTE ON FUNCTION public.set_quotation_status(uuid,text) FROM PUBLIC,anon;
CREATE FUNCTION public.convert_quotation(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.quotations; oid uuid; rows jsonb; doc jsonb; BEGIN IF NOT public.can_access('quotations') OR NOT public.can_access('orders') THEN RAISE EXCEPTION 'Penawaran dan Order wajib berizin'; END IF; SELECT * INTO q FROM public.quotations WHERE id=p_id AND tenant_id=public.active_tenant_id() AND deleted_at IS NULL FOR UPDATE; IF q.id IS NULL OR q.status<>'disetujui' OR q.converted_order_id IS NOT NULL OR q.valid_until<(now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Penawaran belum disetujui, kedaluwarsa, atau sudah dikonversi'; END IF; SELECT jsonb_agg(to_jsonb(i)-'id' ORDER BY position) INTO rows FROM public.quotation_items i WHERE quotation_id=q.id AND tenant_id=q.tenant_id AND deleted_at IS NULL; doc:=to_jsonb(q)-'tenant_id'-'id'; doc:=doc||jsonb_build_object('document_date',(now() AT TIME ZONE 'Asia/Jakarta')::date); oid:=public.save_sales_document('orders',NULL,doc,rows); UPDATE public.orders SET po_number=q.quotation_number WHERE id=oid; UPDATE public.quotations SET converted_order_id=oid WHERE id=q.id; RETURN oid; END $$;
GRANT EXECUTE ON FUNCTION public.convert_quotation(uuid) TO authenticated; REVOKE EXECUTE ON FUNCTION public.convert_quotation(uuid) FROM PUBLIC,anon;
CREATE FUNCTION public.sales_pricelist() RETURNS TABLE(id uuid,name text,unit text,price numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT(public.can_access('orders') OR public.can_access('quotations')) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; RETURN QUERY SELECT p.id,p.name,p.unit,p.price FROM public.pricelist_items p WHERE p.tenant_id=public.active_tenant_id() AND p.deleted_at IS NULL AND p.is_active ORDER BY p.name; END $$;
GRANT EXECUTE ON FUNCTION public.sales_pricelist() TO authenticated; REVOKE EXECUTE ON FUNCTION public.sales_pricelist() FROM PUBLIC,anon;